import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $findMatchingParent, mergeRegister } from "@lexical/utils";
import { CAN_UNDO_COMMAND, COMMAND_PRIORITY_CRITICAL, CAN_REDO_COMMAND, SELECTION_CHANGE_COMMAND, $getSelection, $isRangeSelection, $isRootOrShadowRoot, } from "lexical";
import { useRef, useEffect, useState, useCallback } from "react";
import { $getCommonAncestorCompatible, $getSelectedParaMarkerPara, $isBookNode, $isParaNode, $isImmutableChapterNode, $isVerseBlockNode, } from "shared";
import { $isReactNodeWithMarker } from "../../nodes/usj/node-react.utils";
/** Plugin to track state and update parent component state */
export function StateChangePlugin({ onStateChange }) {
    const [editor] = useLexicalComposerContext();
    const [activeEditor, setActiveEditor] = useState(editor);
    const canUndoRef = useRef(false);
    const canRedoRef = useRef(false);
    const blockMarkerRef = useRef(undefined);
    const contextMarkerRef = useRef(undefined);
    const $updateState = useCallback(() => {
        const selection = $getSelection();
        // A selected paragraph marker names its block outright: the paragraph that owns it. Not while
        // read-only, where the marker selection is inert.
        const selectedMarkerOwner = activeEditor.isEditable()
            ? $getSelectedParaMarkerPara(selection)
            : undefined;
        if (selectedMarkerOwner &&
            activeEditor.getElementByKey(selectedMarkerOwner.getKey()) !== null) {
            blockMarkerRef.current = selectedMarkerOwner.getMarker();
            contextMarkerRef.current = selectedMarkerOwner.getMarker();
            onStateChange?.({
                canUndo: canUndoRef.current,
                canRedo: canRedoRef.current,
                blockMarker: blockMarkerRef.current,
                contextMarker: contextMarkerRef.current,
            });
            return;
        }
        let contextMarker;
        if ($isRangeSelection(selection)) {
            const anchorNode = selection.anchor.getNode();
            const focusNode = selection.focus.getNode();
            let node = anchorNode.getKey() === "root"
                ? anchorNode
                : $findMatchingParent(anchorNode, (e) => {
                    const parent = e.getParent();
                    return parent !== null && $isRootOrShadowRoot(parent);
                });
            if (node === null) {
                node = anchorNode.getTopLevelElementOrThrow();
            }
            // In the block verse layout the top-level element is the verse block, which carries no
            // marker of its own. The block marker the host wants is still the paragraph inside it that
            // holds the caret, so resolve through the block. `$isParaNode`, not `$isSomeParaNode`: an
            // implied paragraph has no marker to report, and the reporting guard below is the same
            // predicate - resolving to a node that guard then rejects would emit no state change at all.
            if ($isVerseBlockNode(node))
                node = $findMatchingParent(anchorNode, $isParaNode) ?? node;
            const nodeKey = node.getKey();
            const elementDOM = activeEditor.getElementByKey(nodeKey);
            const contextNode = $getCommonAncestorCompatible(anchorNode, focusNode);
            if (contextNode && $isReactNodeWithMarker(contextNode)) {
                contextMarker = contextNode.getMarker();
            }
            if (elementDOM !== null &&
                ($isParaNode(node) || $isBookNode(node) || $isImmutableChapterNode(node))) {
                blockMarkerRef.current = node.getMarker();
                contextMarkerRef.current = contextMarker;
                onStateChange?.({
                    canUndo: canUndoRef.current,
                    canRedo: canRedoRef.current,
                    blockMarker: blockMarkerRef.current,
                    contextMarker,
                });
                return;
            }
        }
        contextMarkerRef.current = contextMarker;
    }, [activeEditor, onStateChange]);
    useEffect(() => {
        return editor.registerCommand(SELECTION_CHANGE_COMMAND, (_payload, newEditor) => {
            $updateState();
            setActiveEditor(newEditor);
            return false;
        }, COMMAND_PRIORITY_CRITICAL);
    }, [editor, $updateState]);
    useEffect(() => {
        return mergeRegister(activeEditor.registerUpdateListener(({ editorState }) => {
            editorState.read(() => {
                $updateState();
            });
        }), activeEditor.registerCommand(CAN_UNDO_COMMAND, (payload) => {
            canUndoRef.current = payload;
            onStateChange?.({
                canUndo: canUndoRef.current,
                canRedo: canRedoRef.current,
                blockMarker: blockMarkerRef.current,
                contextMarker: contextMarkerRef.current,
            });
            return false;
        }, COMMAND_PRIORITY_CRITICAL), activeEditor.registerCommand(CAN_REDO_COMMAND, (payload) => {
            canRedoRef.current = payload;
            onStateChange?.({
                canUndo: canUndoRef.current,
                canRedo: canRedoRef.current,
                blockMarker: blockMarkerRef.current,
                contextMarker: contextMarkerRef.current,
            });
            return false;
        }, COMMAND_PRIORITY_CRITICAL));
    }, [$updateState, activeEditor, onStateChange]);
    return null;
}
