/** Spaces in runs display as NBSP so they are visible while typing, and a lone display NBSP left
 * standing on its own goes back to a plain space ({@link $isLeftoverDisplaySpace}). */
export function $displayWhitespaceTransform(node: TextNode): void {
  const text = node.getTextContent();
  const isLoneNbsp = text === NBSP;
  if (!isLoneNbsp && !text.includes(" ")) return;
  const textType = $getState(node, textTypeState);
  if (textType === "attribute" || textType === MARKER_TRAILING_SPACE_TEXT_TYPE) return;
  // An expanded note's caller slot is a structural space, the caller, and a structural NBSP -
  // with the caller deleted, just the two separators, which this mapping would turn into two
  // NBSPs and the caller's own transform straight back, forever. The caller's transform owns it.
  if ($isNoteCallerSlot(node)) return;
  for (let parent = node.getParent(); parent; parent = parent.getParent()) {
    // Note content and the `\id` line's content both display space runs as NBSP like any other
    // content — the USJ->editor adaptor already display-maps their text on load, so mapping while
    // typing is what keeps the live shape and the loaded one the same. A chapter's own text is its
    // `\c N` glyph rather than content, and unknown blocks keep literal text (degradation
    // property), so neither has a content run to map.
    if ($isChapterNode(parent) || $isUnknownNode(parent)) return;
  }
  if (isLoneNbsp) {
    if ($isLeftoverDisplaySpace(node)) node.setTextContent(" ");
    return;
  }
  // A char span's text children carry a STRUCTURAL leading NBSP (the glyph separator the
  // adaptor/materializer glues onto content). It is not a display space-run member, so it must
  // not act as left context for the mapping: a genuine content-leading single space stays plain
  // in the clean-loaded shape, and mapping it here would make edited (dirty) nodes emit
  // different collab ops than clean-loaded ones for identical content.
  const hasStructuralPrefix = text.startsWith(NBSP) && $isCharNode(node.getParent());
  const body = hasStructuralPrefix ? text.slice(1) : text;
  const mapped =
    (hasStructuralPrefix ? NBSP : "") +
    body
      .replace(/ (?=[ \u00A0])/g, NBSP) // space followed by space/NBSP
      .replace(/(?<=\u00A0) /g, NBSP); // space preceded by NBSP
  if (mapped !== text) node.setTextContent(mapped); // length-preserving: caret stays valid
}

/**
 * Makes a no-break space the user types go in as `getNbspSpelling()`'s display form whenever that
 * is not `~` — the case where the project stores U+00A0 itself, so the character is data and is
 * kept. With the `~` spelling a typed U+00A0 is left alone: it is display spacing there and saves
 * as a space, as in Paratext 9, whose authors type a no-break space as `~`. A typed C0 control
 * character other than tab, line feed and carriage return goes in as a space either way
 * ({@link controlCharactersToSpaces}), so a typed U+001A never becomes the stand-in for a stored
 * no-break space.
 *
 * Two routes carry typed text, and both are covered: `CONTROLLED_TEXT_INSERTION_COMMAND` (Lexical
 * dispatches it when it inserts the text itself) is re-dispatched with the text respelled, and a
 * `beforeinput` the browser would otherwise apply to the DOM itself (Lexical then reads the text
 * back without a command) is claimed in the capture phase, ahead of Lexical's own listener, and
 * inserted through the command. Text being composed by an input method is left alone.
 *
 * @param editor - The editor.
 * @param getNbspSpelling - The current spelling, read at each insertion.
 * @returns The teardown.
 */
export function registerTypedNbspSpelling(
  editor: LexicalEditor,
  getNbspSpelling: () => string,
): () => void {
  const respelled = (text: string | null | undefined): string | undefined => {
    if (!text) return undefined;
    const nbspSpelling = getNbspSpelling();
    let result = controlCharactersToSpaces(text);
    if (nbspSpelling !== "~") result = result.replaceAll(NBSP, nbspSpelling);
    return result === text ? undefined : result;
  };
  // Set while the respelled text is inserted, which holds the stand-in: respelling it again would
  // read that stand-in as a typed control character.
  let isInsertingRespelled = false;
  const insertRespelled = (text: string) => {
    isInsertingRespelled = true;
    try {
      editor.dispatchCommand(CONTROLLED_TEXT_INSERTION_COMMAND, text);
    } finally {
      isInsertingRespelled = false;
    }
  };
  const onBeforeInput = (event: InputEvent) => {
    if (event.inputType !== "insertText" || editor.isComposing()) return;
    const text = respelled(event.data);
    if (text === undefined) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    insertRespelled(text);
  };
  return mergeRegister(
    editor.registerCommand(
      CONTROLLED_TEXT_INSERTION_COMMAND,
      (payload) => {
        if (isInsertingRespelled || editor.isComposing()) return false;
        const text = respelled(typeof payload === "string" ? payload : payload.data);
        if (text === undefined) return false;
        insertRespelled(text);
        return true;
      },
      COMMAND_PRIORITY_CRITICAL,
    ),
    editor.registerRootListener((root, previousRoot) => {
      previousRoot?.removeEventListener("beforeinput", onBeforeInput, true);
      root?.addEventListener("beforeinput", onBeforeInput, true);
    }),
    () => editor.getRootElement()?.removeEventListener("beforeinput", onBeforeInput, true),
  );
}

/**
 * Whether `node`, an untagged text that is exactly one NBSP, is what is left of a displayed space
 * run — two spaces between two elements (char spans, notes, milestones) display as two NBSPs, and a
 * backspace leaves one — rather than one of the engine's structural lone-NBSP nodes. Content NBSP
 * displays as its spelling (`~`, or `NBSP_STAND_IN`), so in content a lone NBSP is one or the other.
 * A plain space is the shape the same single space loads as, so it goes back to one. This holds at
 * every depth — in a paragraph, inside a char span, and directly inside an expanded note.
 *
 * Every structural lone NBSP sits where this says no — in Standard view, a superset of the display
 * slots `$isLoneNbspContent` (node.utils.ts) rules out:
 *
 * - right after a marker glyph: an empty span's placeholder (`EMPTY_CHAR_PLACEHOLDER_TEXT`), the
 *   spacer in front of a span's leading nested element, a separator a split stranded, and a
 *   paragraph's or note's separator that lost its tag;
 * - first in a char span or note: the spacer that followed an opening glyph the user deleted,
 *   before the span unwraps;
 * - directly under a note with a collapsed caller (`ImmutableNoteCallerNode`): its display
 *   separators, and the bare separator `NoteNodePlugin` turns into its tagged one after the caller
 *   or a top-level span;
 * - inside or beside an annotation mark, where a lone NBSP may be content the wrap split off
 *   (`$isNbspContentAtMark`) or a run piece the mark separated from the rest of its run — the
 *   editor→USJ conversion already keeps those as content;
 * - inside an attribute display run.
 *
 * Nor is a token-mode or tagged node one; a note's caller slot, and chapter and unknown-block text,
 * are ruled out before this is asked.
 *
 * Read-only: call inside `editor.update()` or an editor-state read.
 */
function $isLeftoverDisplaySpace(node: TextNode): boolean {
  if (node.getMode() !== "normal" || $getState(node, textTypeState) !== undefined) return false;
  const parent = node.getParent();
  if ($isTypedMarkNode(parent) || $isAttributeRunNode(parent)) return false;
  if ($isNoteNode(parent) && parent.getChildren().some($isImmutableNoteCallerNode)) return false;
  const previous = node.getPreviousSibling();
  // A span's or note's opening glyph always comes first, so a leftover space never does; a first
  // child is the spacer that followed a glyph the user deleted.
  if (($isCharNode(parent) || $isNoteNode(parent)) && !previous) return false;
  const next = node.getNextSibling();
  return !$isMarkerNode(previous) && !$isTypedMarkNode(previous) && !$isTypedMarkNode(next);
}

/**
 * Pasted text of a `text/html` clipboard payload. A bare `body.textContent` read is not enough:
 * it merges the last word of one block into the first word of the next (`<p>a</p><p>b</p>` →
 * "ab"), and a body-level `<script>`/`<style>` would contribute its source text as pasted
 * content. So: script/style/template text is dropped (code, not content), and block boundaries
 * plus `<br>` become newlines — the same newline-joined shape a multi-line `text/plain` paste
 * hands to `insertText` in `$handlePasteForStandardView` below. Deliberately minimal — not a
 * general html-to-text conversion. Exported because {@link getPastePayload} hands this decoding
 * to every paste claim as its fallback for a clipboard that carries `text/html` without any
 * `text/plain`.
 */
export function htmlPasteText(html: string): string {
  // DOMParser yields an inert document: parsing never executes scripts or loads subresources,
  // and no node from the parsed document is ever adopted into the live DOM — only text content
  // is read out of it.
  const { body } = new DOMParser().parseFromString(html, "text/html");
  body.querySelectorAll("script,style,template").forEach((element) => element.remove());
  body.querySelectorAll("br").forEach((element) => element.replaceWith("\n"));
  body
    .querySelectorAll("p,div,li,td,th,tr,h1,h2,h3,h4,h5,h6,blockquote,pre")
    .forEach((element) => element.after("\n"));
  // Collapse boundary-newline runs (nested blocks, source formatting) and trim the outermost
  // ones; only `\n` is touched — an NBSP at either end must survive (String.trim would eat it).
  return (body.textContent ?? "").replace(/\n+/g, "\n").replace(/^\n|\n$/g, "");
}

/** The text of a paste, read the one way every `PASTE_COMMAND` claim in this editor reads it. */
export interface PastePayload {
  /**
   * What a claim replays: the USFM decoded from a Paratext 9 clipboard's `text/html` when the html
   * is one and decodes to anything, else `text/plain` when it carries anything, else the decoded
   * `text/html`. Some sources
   * (word processors, intermediaries) ship html alone, and those pastes otherwise reach the generic
   * handling this editor's claims exist to pre-empt.
   *
   * The unresolved carriers (`text/plain`, the raw `text/html`, and its decoded text) are
   * deliberately not exposed alongside it: every claim must replay the SAME bytes, and a second
   * carrier within reach is an invitation for one of them to pick differently. A claim that ever
   * genuinely needs one can read the clipboard for it, at its own site, with its own reason.
   */
  text: string;
  /**
   * Whether the clipboard carries a rich payload (`application/x-lexical-editor`) that LEXICAL'S
   * OWN fast path will reconstruct as real nodes — which is what a declining claim hands the paste
   * to, and therefore the only question a decline can safely turn on. That path is
   * namespace-scoped: `$insertDataTransferForRichText` (`@lexical/clipboard`) takes the node-tree
   * branch only for `payload.namespace === editor._config.namespace` with a `nodes` array, and
   * falls through to the `text/html` DOM import for everything else. A payload written by a
   * DIFFERENT Lexical editor — the `"Commenting"` editor `CommentPlugin.tsx` mounts in this same
   * app writes one — is therefore FOREIGN here: answering true for it would make every claim stand
   * aside for a path that runs none of this editor's byte rules, so a `\c` copied out of a comment
   * box would reach the document unstripped.
   *
   * Deliberately NOT acted on here: the claims disagree about it on purpose — the in-note `\fp`
   * claim covers internal pastes (an internal multi-paragraph copy is exactly the split it
   * prevents), the char-stack claim declines them outright, and the Standard-view claim declines
   * them EXCEPT when the selection touches an attribute display run, where plain-text insertion
   * is the only safe shape whatever else the clipboard carries — so each one applies its own
   * rule, in view, at its own site.
   */
  isInternal: boolean;
}

/**
 * Whether `lexicalString` is a rich payload Lexical's own paste would reconstruct as NODES in an
 * editor with this `namespace` — the exact condition `$insertDataTransferForRichText`
 * (`@lexical/clipboard`) applies before taking its node-tree branch. Anything else (a foreign
 * editor's namespace, a missing `nodes` array, unparseable JSON, no flavor at all) falls through
 * that function to the `text/html` DOM import, which is an ORDINARY external paste as far as this
 * editor's rules are concerned.
 *
 * Mirrored rather than imported because Lexical exports no predicate for it.
 */
function isSameNamespaceLexicalPayload(lexicalString: string, namespace: string): boolean {
  if (!lexicalString) return false;
  try {
    const payload: unknown = JSON.parse(lexicalString);
    if (typeof payload !== "object" || payload === null) return false;
    const { namespace: payloadNamespace, nodes } = payload as {
      namespace?: unknown;
      nodes?: unknown;
    };
    return payloadNamespace === namespace && Array.isArray(nodes);
  } catch {
    return false;
  }
}

/**
 * Pull the pasted text out of a `PASTE_COMMAND` payload. `undefined` when the payload carries no
 * clipboard at all (a KeyboardEvent-shaped dispatch, or an event whose data store is
 * inaccessible), which every claim reads as "not mine".
 *
 * THREE handlers replay the pasted bytes and so must agree on them byte-for-byte, or the same
 * clipboard is one thing to one of them and another to the next: the in-note `\fp` claim at
 * CRITICAL, and the Standard-view external-paste claim and the char-stack line replay at HIGH
 * (`MarkerEditPlugin.tsx`). All three read the clipboard only through here: the jsdom-safe
 * duck-check (jsdom implements no `ClipboardEvent`, so `instanceof` against the undefined global
 * throws), the carrier choice below, and line-ending normalization BEFORE any caller tests for a
 * line break — so `\r\n` and bare-`\r` clipboards break correctly and no `\r` ever reaches content
 * on any path.
 *
 * Other handlers race on the same command without going through this, correctly: the LOW
 * paragraph-split arm (`MarkerEditPlugin.tsx`) only sets a flag and never looks at the payload,
 * and shared-react's `StructureKeyboardPlugin` (HIGH) and `CommandMenuPlugin` (NORMAL) read the
 * clipboard directly for their own decisions — sanitizing and gating, not replaying — so they have
 * nothing to agree with the three about.
 */
export function getPastePayload(
  event: PasteCommandType | null | undefined,
  namespace: string,
): PastePayload | undefined {
  const clipboardData =
    event && typeof event === "object" && "clipboardData" in event
      ? event.clipboardData
      : undefined;
  if (!clipboardData) return undefined;
  return getDataTransferPayload(clipboardData, namespace);
}

/**
 * Read a paste's clipboard or a drop's data store into the text every claim replays — the carrier
 * choice {@link getPastePayload} describes — so a paste and a drop of the same content are the same
 * bytes to every claim that handles both.
 */
export function getDataTransferPayload(
  dataTransfer: DataTransfer,
  namespace: string,
): PastePayload {
  const normalizeLineEndings = (text: string) => text.replace(/\r\n?/g, "\n");
  const plainText = normalizeLineEndings(dataTransfer.getData("text/plain"));
  const html = dataTransfer.getData("text/html");
  // A Paratext 9 clipboard's html is decoded to USFM and WINS over its own `text/plain`
  // (`paratext9Clipboard.utils.ts`) whenever the decode has anything in it; every other source's
  // `text/plain` wins whenever it carries anything; a clipboard with only `text/html` falls back to
  // that html's decoded text. A P9 fragment can match the signature and still decode to nothing
  // (all of it in `exclude` spans with no `usfm:` comment), and its own `text/plain` is then the
  // better carrier than an empty paste. The html is decoded only when the choice reaches it: a
  // word processor's or browser's html routinely runs to hundreds of KB beside the `text/plain`
  // that wins, and every claim reads the payload.
  //
  // The P9 clause is the one place a source's html is strictly MORE faithful than its plain text, and
  // it is more faithful by construction rather than by luck: P9 writes `text/plain` as the selection's
  // VISIBLE text, while the USFM its own paste reads rides the html as escaped `<!--usfm:…-->`
  // comments inside spans P9 marks `exclude`. A footnote's `text/plain` is therefore the caller GLYPH
  // alone (`a`, or `*`), and reading it drops the whole note. The decoder's signature is what keeps
  // this from becoming a general "prefer html" rule: it answers `undefined` for every html that is not
  // a P9 scripture-editor fragment, this editor's own included.
  //
  // For everything else the carrier is chosen by PRESENCE — plain text whenever the clipboard carries
  // any — and not by which carrier an NBSP survived in. The stronger NBSP rule is genuinely better for
  // a foreign clipboard: a source whose `text/plain` collapsed `&nbsp;` to a plain space still has the
  // real NBSP in its `text/html`, and preferring html there would keep a data-NBSP this loses. It buys
  // nothing on this editor's OWN copy, whose two readable flavors are the same USFM bytes
  // ({@link $getStandardViewClipboardData}) — so the plain carrier stays authoritative and the foreign
  // data-NBSP loss is accepted.
  const paratext9Text = html ? paratext9HtmlToUsfm(html) : undefined;
  return {
    // Control characters become spaces, as Paratext would read them, before any claim sees the text:
    // U+001A is the editor's stand-in for a stored no-break space (`controlCharactersToSpaces`).
    text: controlCharactersToSpaces(
      paratext9Text
        ? normalizeLineEndings(paratext9Text)
        : plainText || (html ? normalizeLineEndings(htmlPasteText(html)) : ""),
    ),
    isInternal: isSameNamespaceLexicalPayload(
      dataTransfer.getData("application/x-lexical-editor"),
      namespace,
    ),
  };
}

/**
 * A marker token this handler recognizes for positional NBSP normalization: a plain or
 * nested-char marker (`\nd`, `\+nd`), either one's closer (`\nd*`, `\+nd*`), or a milestone's
 * anonymous self-closer (`\*`).
 *
 * Built from the engine's liberal name class, not the canonical one: this is RECOGNIZING a
 * marker-shaped byte run in arbitrary pasted text, which is exactly the job that class exists for,
 * and a name the tokenizer will read as a marker has to be read as one here too — otherwise its
 * separator NBSP survives into content as a data `~`.
 */
const MARKER_TOKEN = String.raw`\\(?:\+?[${ENGINE_MARKER_NAME_BYTES}]+\*?|\*)`;

/**
 * An NBSP directly after a marker token or directly before one — the two adjacencies
 * {@link normalizePastedNbsp} resolves to a plain space. One alternation rather than a pass each,
 * so the two directions cannot drift apart in what they recognize or in what they substitute; the
 * lookbehind and lookahead read as the mirror images the rule actually is.
 */
const MARKER_ADJACENT_NBSP = new RegExp(
  String.raw`(?<=${MARKER_TOKEN})\u00A0|\u00A0(?=${MARKER_TOKEN})`,
  "g",
);

/**
 * Positional NBSP normalization for an external paste's resolved text. Standard view has no
 * `text/html` fidelity carrier for foreign sources (`$handlePasteForStandardView` below drops
 * formatting entirely and re-tokenizes the plain text — a Paratext 9 clipboard is the one source
 * whose html IS read for fidelity, and it is decoded to USFM outright before reaching here, with
 * every NBSP already resolved to the space it stands for: {@link getPastePayload}), so a
 * `text/html` payload's NBSPs are the only clue to which spaces were meaningful markup vs. plain
 * content — and the browser's own
 * clipboard round-trip (and a same-editor paste, whose private Lexical flavor does not survive
 * `navigator.clipboard.read()` — see `$handlePasteForStandardView`'s doc comment) both carry a
 * DISPLAY-NBSP (a Standard-view run space, a marker's own trailing separator, or a note's
 * internal spacer — `createNote` in `usj-editor.adaptor.ts` appends one after EVERY child, not
 * just the first, so one sits directly before `\ft`/`\f*` and every other child after the caller)
 * as a real NBSP, indistinguishable at this point from a genuine data-NBSP (PT9's `~` glyph).
 *
 * The two are told apart POSITIONALLY, mirroring PT9's `PostprocessUsfm`, in three passes:
 *
 * 1. A leading NBSP run — at the very start of the text, or right after a newline (a later
 *    paragraph of a multi-line paste can itself start mid-span) — reads as display spacing with
 *    nothing in front of it to match against (a partial selection starting exactly at a char
 *    span's structural leading NBSP, or inside a paragraph-leading space run, which Standard view
 *    stores as all-NBSP) and becomes plain spaces, one per NBSP.
 * 2. An NBSP immediately FOLLOWING a marker token is the required opener/closer separator and
 *    becomes a plain space (e.g. the mandatory space after `\f`/`\fr`, or a char span's own
 *    leading separator when the marker literal IS present in the pasted text).
 * 3. An NBSP immediately PRECEDING a marker token becomes a plain space — `the\u00A0\nd Lord`
 *    keeps the space between its words, and `\nd Lord\u00A0\nd*` keeps its span's trailing space.
 *    None is dropped, even where a note's display layout puts a spacer (before a child's marker or
 *    the note's own `\f*`): no copy this editor makes puts that layout on the clipboard (Standard
 *    view and the Markers view both copy USFM), a foreign carrier holding a copy of the display is
 *    the only source left, and telling its spacers apart from a space the user typed there is not
 *    possible from the text alone. Keeping a spacer costs a stray space; dropping a user's space
 *    loses content.
 *
 * Rules 2 and 3 run as ONE pass over `MARKER_ADJACENT_NBSP`, so a marker recognized on one side is
 * recognized on the other and both resolve to the same byte. Every remaining NBSP is genuine data
 * and is preserved as `nbspSpelling`, the display form a stored NBSP takes (`~`, or `NBSP_STAND_IN`
 * where `~` is an ordinary character — `getNbspSpelling`), so serialization round-trips it to a
 * real NBSP instead of silently collapsing it to a plain space or dropping it. A pasted `~` is
 * never touched: it is the display form already, or an ordinary character.
 *
 * @param text - The paste's resolved text.
 * @param nbspSpelling - What a stored NBSP displays as; `~` by default.
 */
export function normalizePastedNbsp(text: string, nbspSpelling = "~"): string {
  return text
    .replace(/^\u00A0+/gm, (run) => " ".repeat(run.length))
    .replace(MARKER_ADJACENT_NBSP, " ")
    .replaceAll(NBSP, nbspSpelling);
}

/** A `\c` chapter token ANYWHERE in a line: the marker, its separator, and the ONE
 * whitespace-delimited word the tokenizer reads as the chapter number (`getNextWord`,
 * usfmFragmentToUsj.ts) — and nothing more, because everything past that word is ordinary content
 * the paste must keep. Stops at a backslash too, so `\c\nd x` strips the bare `\c` and leaves
 * `\nd x` whole. Not anchored to the line's start: a chapter token can sit mid-line (`x \c 5 y`,
 * a paste landing mid-sentence), and an anchor there would silently miss it. Global so more than
 * one occurrence on the same line is fully swept, not just the first. */
const CHAPTER_TOKEN = new RegExp(
  String.raw`\\c(?![${ENGINE_MARKER_NAME_BYTES}])[ \u00A0]*[^\s\\]*`,
  "g",
);

/** A `\id` book-id token ANYWHERE in a line, capturing its payload up to — but not including —
 * the next marker or line end. Wider than {@link CHAPTER_TOKEN} on purpose: an `\id` line's whole
 * remainder IS the token's payload (book code plus an optional free-text description), so there is
 * no trailing content to preserve the way there is after a chapter number. */
const BOOK_ID_TOKEN = new RegExp(String.raw`\\id(?![${ENGINE_MARKER_NAME_BYTES}])[^\n\\]*`, "g");

/**
 * Either stripped token at the very START of a line — the one placement whose whole line may be
 * dropped. Non-global on purpose: `.test` on a global regex carries `lastIndex` between calls.
 */
const LINE_LEADING_STRIPPED_TOKEN = new RegExp(
  String.raw`^(?:${CHAPTER_TOKEN.source}|${BOOK_ID_TOKEN.source})`,
);

/**
 * Drops every pasted `\c`/`\id` token and its payload (the chapter number / book code, up to the
 * next marker or newline) before insertion. Both create a document-structural node PT9 allows
 * only once per book (a `ChapterNode`/`BookNode`, materialized from the marker name alone —
 * `usj-editor.adaptor.ts` — same as a real load), and Standard view has no per-paste "am I the
 * only one" check the way an initial document load does. A pasted bare `\c 2` mid-chapter would
 * otherwise create a second chapter node in the editor, and every subsequent save would then fail
 * with the PDP's "Multiple chapter markers present" (an error that surfaces only in the renderer
 * log — disk and other editors would silently stop updating). `\id` is the book-level twin of the
 * same hazard and is stripped identically. A token need not be its own line — `x \c 5 y`
 * mid-paragraph reaches the same tokenizer branch (chapter/book-id tokens are recognized wherever
 * they occur, not just at a fragment's start) and left unstripped produces the identical poisoned
 * shape: a second chapter node PLUS the trailing bytes (`y`) stranding as a bare top-level USJ
 * string outside any paragraph, since a chapter token closes the enclosing paragraph the same way
 * it does on a real load.
 *
 * Only the token's OWN bytes go: `\c` plus the one word the tokenizer reads as the chapter
 * number. Content that merely follows it on the same line is the user's and survives — `x \c 5 y`
 * strips to `x  y`, not to `x `. Removing more would trade one silent corruption for another, and
 * the poisoning this exists to prevent is fully undone once the marker and its number are gone.
 * A token sharing a line with a LATER marker — `\c 5\v 1 In the beginning` — likewise only loses
 * its own bytes: both token regexes stop at the next `\`.
 *
 * Splits on lines and strips per line (not one global pass over the whole text) so a token that
 * consumes an ENTIRE line can cleanly take that line's own newline with it too (no stray empty
 * paragraph left behind). Only a line the token OPENS may go whole: whatever whitespace trails it
 * is the glyph's own separator (a chapter line copies as `\c 5 `, and the token stops short of
 * that space), so it goes with the token. Whitespace BEFORE the token is the user's: a space or
 * NBSP ahead of `\c 5` survives as a one-character line instead of going with the token, because
 * a byte the user wrote is never dropped. A line that was ALREADY blank in the source paste
 * (nothing to do with `\c`/`\id`) is left alone.
 *
 * Exported for the in-note CRITICAL multi-line paste claim (`MarkerEditPlugin.tsx`), which shares
 * this strip the same way it shares `normalizePastedNbsp` — a `\c`/`\id` token pasted into note
 * content is just as reachable (the note-content Tier 2 rebuild tokenizes literal text the same
 * way a paragraph rebuild does) and just as harmful there.
 */
export function stripPastedChapterAndBookId(text: string): string {
  return text
    .split("\n")
    .map((line) => {
      const stripped = line.replace(CHAPTER_TOKEN, "").replace(BOOK_ID_TOKEN, "");
      // Anchored, so the line goes only when the token is what opened it. A token further in
      // leaves whatever preceded it behind, whitespace included: that byte is content the user
      // wrote, and dropping the line would take it — and the line break — with the token.
      const isTokenOnlyLine =
        LINE_LEADING_STRIPPED_TOKEN.test(line) && stripped.trim() === "" && line.trim() !== "";
      return isTokenOnlyLine ? undefined : stripped;
    })
    .filter((line): line is string => line !== undefined)
    .join("\n");
}

/**
 * A `\v` token: the marker, its separator, the one word the tokenizer reads as the verse number, and
 * the one space that ends the token — the same shape {@link CHAPTER_TOKEN} reads for a chapter.
 */
const VERSE_TOKEN = new RegExp(
  String.raw`\\v(?![${ENGINE_MARKER_NAME_BYTES}*])[ \u00A0]*[^\s\\]*[ \u00A0]?`,
  "g",
);

/**
 * An opening marker with no `+` and no closing `*`, and the one space that ends it — the only shape
 * a paragraph marker takes. Whether it IS one is the stylesheet's to say (see
 * {@link stripPastedBlockMarkers}).
 */
const PLAIN_OPENER_TOKEN = new RegExp(
  String.raw`\\([${ENGINE_MARKER_NAME_BYTES}]+)(?![${ENGINE_MARKER_NAME_BYTES}*])[ \u00A0]?`,
  "g",
);

/**
 * Drops every structure marker from a structure-protected paste, keeping the text around it: every
 * paragraph-kind marker the stylesheet knows, and `\v` with its verse number (`\c` and `\id` are
 * already gone — {@link stripPastedChapterAndBookId}). These are the markers structure protection
 * keeps a user from TYPING — Platform.Bible's marker menu disables exactly this set under protection
 * — and pasted text re-tokenizes into real markers the same way typed text does, so without this a
 * paste could add a verse or split a paragraph that the keyboard could not. Character markers, notes
 * and figures are content and stay. A marker the stylesheet does not know stays too — its bytes
 * cannot be classified, and dropping bytes a strip cannot classify loses user content — but a known
 * gap remains under protection: in body text the tokenizer reads an unrecognized marker as a
 * PARAGRAPH regardless of the stylesheet, the same as PT9's `DetermineUnknownTokenType`
 * (`usfmFragmentToUsj.ts`), so a protected paste of an unknown marker can still split the paragraph,
 * exactly as typing it would.
 *
 * Each token goes with the one space that separates it from the text after it, so `aa \v 9 bb`
 * becomes `aa bb` and `\p text` becomes `text`.
 *
 * @param text The paste's text, `\c`/`\id` already stripped.
 * @param getMarker The editor's stylesheet lookup.
 */
export function stripPastedBlockMarkers(text: string, getMarker: MarkerLookup): string {
  return text
    .replace(VERSE_TOKEN, "")
    .replace(PLAIN_OPENER_TOKEN, (token, name: string) =>
      getMarker(name)?.type === MarkerType.Paragraph ? "" : token,
    );
}

/**
 * True when `node` is part of an attribute display run: a TextNode tagged textType "attribute"
 * (a char span's bare `|…` run, a verse's `\va`/`\vp` value, or a milestone's attribute text — all
 * three share this one tag), or `node` itself / one of its ancestors is an `AttributeRunNode` — the
 * structural wrapper a verse/milestone run rides in, reachable by an element-point selection even
 * when no value text exists yet (an empty `\qt-s \*` run with nothing typed between the glyphs). A
 * char span's run has no such wrapper (it rides as a bare child of the `CharNode`), so the
 * textType tag alone covers it.
 *
 * The `AttributeRunNode`-ancestor branch also matches a selection landing on the wrapper's OWN
 * opening/self-closing `MarkerNode` glyphs (`\va`, `\va*`, a milestone's `\*`), not only its
 * textType-"attribute" value text — deliberately: a `MarkerNode` is itself an ordinary `TextNode`,
 * so `selection.insertText` at a glyph point behaves exactly as it would for typing there (the
 * same paste-≡-typing guarantee this whole file exists to uphold), and it is harmless the same way
 * inserting into any other plain text is.
 */
function $isNodeInAttributeContext(node: LexicalNode): boolean {
  if ($isTextNode(node) && $getState(node, textTypeState) === "attribute") return true;
  for (let ancestor: LexicalNode | null = node; ancestor; ancestor = ancestor.getParent())
    if ($isAttributeRunNode(ancestor)) return true;
  return false;
}

/**
 * True when `selection` touches attribute-display text at EITHER end — its anchor OR its focus
 * satisfies {@link $isNodeInAttributeContext}. A collapsed caret trivially qualifies when its one
 * point does. A real (non-collapsed) selection qualifies even when only ONE end is inside an
 * attribute run and the other reaches into ordinary content: under the paste-≡-typing principle, a
 * user typing a character over such a mixed selection gets exactly `selection.insertText`'s own
 * behavior — remove the whole selected range (whatever nodes it spans, attribute or not), then
 * insert at the resulting collapsed point — so paste must take the identical path rather than
 * declining into a branch (Lexical's rich-node paste, or this file's own newline-splitting
 * external-paste pipeline) that can corrupt the attribute-run end of the range. See
 * `$handlePasteForStandardView`'s doc comment for the two corruption shapes this closes.
 */
function $isSelectionInAttributeContext(selection: RangeSelection): boolean {
  return (
    $isNodeInAttributeContext(selection.anchor.getNode()) ||
    $isNodeInAttributeContext(selection.focus.getNode())
  );
}

/**
 * True when the WHOLE of `selection` stays inside ONE attribute-display node — a collapsed caret in
 * attribute context, or a range whose anchor and focus are the same node and that node is in
 * attribute context.
 *
 * This is the only shape whose pasted bytes are genuinely attribute VALUE bytes, and therefore the
 * only one whose value-byte carve-outs ({@link $insertPastedTextIntoAttributeContext}) are earned.
 * What earns them is paste ≡ TYPING: the bytes land where the same keystrokes would land, and this
 * editor's whole attribute-context contract is that a paste in a value behaves as typing there
 * does. The bytes DO still re-tokenize: the `"attribute"` tag survives the insertion, but the
 * caret-departure settle re-tokenizes the paragraph, so a pasted `\c 5` in a value becomes a
 * chapter marker. It becomes one identically when TYPED, so this is the typed-`\c` hole, reached
 * through a different door — not something paste introduces. Extending the strip to cover it would eat bytes out of an attribute value that were
 * never a chapter token — the very regression the carve-out exists to prevent — and would break the
 * equivalence. Both halves are pinned settled, on concrete USJ, in
 * `attributeContextPasteFidelity.test.tsx`.
 *
 * A selection that merely TOUCHES attribute context does not land in a value at all. Removing the
 * range takes the bytes out of the run, and when the range covers a char span's closing glyph it
 * deletes the closer too, so what arrives is ordinary paragraph content. That holds both ways
 * round: a range starting in body text and reaching INTO the run, and a range starting inside the
 * run and reaching PAST the closer. Those bytes get body content's rules, which is a divergence from typing
 * in exactly the two places body paste always diverges from it.
 */
function $isSelectionWithinOneAttributeNode(selection: RangeSelection): boolean {
  const { anchor, focus } = selection;
  return anchor.key === focus.key && $isNodeInAttributeContext(anchor.getNode());
}

/**
 * Paste normalization for a selection touching attribute-display text — the binding design
 * principle: paste ≡ typing the same characters at the same caret. Each `\n` in `text` becomes a
 * single space (a PER-NEWLINE replacement, not a run-collapsing one: `"a\n\nb"` becomes `"a  b"`,
 * two spaces, matching what two individual Enter-less keystrokes over an attribute run would
 * produce — attribute values are single-line, so there is no multi-line attribute byte shape to
 * collapse INTO). `text` arrives with bare `\n` line endings ({@link getPastePayload} normalizes
 * them for every paste claim) — no `\r` reaches this function. For a non-collapsed (mixed or
 * fully-inside) selection, `selection.insertText` removes the selected range before inserting, the
 * same as it does for a typed keystroke over that selection — no separate removal step is needed
 * here. The existing attribute pend/settle machinery (`$textNodeTier2Transform`'s attribute-tagged
 * early return, `$resolvePendingMarkers`) takes over identically whether the text arrived by typing
 * or this call.
 *
 * The two BODY-content paste rules — the `\c`/`\id` strip and the positional NBSP mapping, the only
 * two places a paste deliberately diverges from typing the same bytes — are skipped only for a
 * selection that stays wholly inside one attribute node ({@link $isSelectionWithinOneAttributeNode}).
 * There the bytes go where the same keystrokes would put them, and paste must not diverge: a pasted
 * `\c 5` is inserted literally exactly as a typed one is, and a pasted NBSP passes through exactly
 * as a typed one does (`$displayWhitespaceTransform`, this file, skips textType "attribute" nodes
 * outright). What the SETTLE then makes of those bytes is the same for both — a `\c 5` in a value
 * re-tokenizes into a chapter marker whether it was typed or pasted, which is the deferred typed-`\c`
 * hole rather than a paste defect; see {@link $isSelectionWithinOneAttributeNode}. A selection that
 * only TOUCHES an attribute run does not qualify: its bytes end up as ordinary paragraph content, so
 * they get body content's rules. What does NOT
 * change with them is the insertion MECHANISM — one `insertText`, never the paragraph-splitting
 * line replay and never Lexical's rich-paste node insertion, both of which corrupt the
 * attribute-run end of the range. A multi-line payload landing in body content this way therefore
 * still collapses per newline instead of splitting the paragraph; splitting a paragraph the removal
 * has just cut a char span in half in is the corruption this path exists to avoid.
 *
 * Structure protection applies to BOTH shapes, unlike the two rules above: a value-byte paste
 * settles its `\v`/paragraph-marker bytes into a real verse or a split paragraph exactly as a typed
 * one would (measured: a `\v 9` typed or pasted into a `\va` value re-tokenizes into a real verse
 * node, and a `\p` there splits the paragraph, stranding the run's own closer as an unmatched
 * marker in the new one) — protection's rule that a protected paste never adds structure outranks
 * the paste-≡-typing carve-out for exactly the bytes that would become structure, so
 * {@link stripPastedBlockMarkers} runs on both branches under protection.
 */
function $insertPastedTextIntoAttributeContext(
  selection: RangeSelection,
  text: string,
  isStructureProtected: boolean,
  getMarker: MarkerLookup,
  nbspSpelling: string,
): void {
  const valueBytes = $isSelectionWithinOneAttributeNode(selection);
  const resolved = valueBytes
    ? isStructureProtected
      ? stripPastedBlockMarkers(text, getMarker)
      : text
    : normalizePastedNbsp(
        isStructureProtected
          ? stripPastedBlockMarkers(stripPastedChapterAndBookId(text), getMarker)
          : stripPastedChapterAndBookId(text),
        nbspSpelling,
      );
  // Nothing survived the strip, so there is nothing to replace the selection with — see
  // `$handlePasteForStandardView`.
  if (resolved) selection.insertText(resolved.replace(/\n/g, " "));
}

/**
 * Standard-view PASTE normalization: every external paste (no same-namespace
 * `application/x-lexical-editor` payload) is routed through the plain-text USFM carrier instead
 * of Lexical's HTML import — Standard view has markers as real text, so re-tokenizing pasted
 * text is the SAME mechanism that recognizes typed markers, and it is the only carrier that
 * survives `navigator.clipboard.read()` at all: Chromium's async clipboard-read API exposes only
 * a fixed sanctioned MIME allow-list (`text/plain`, `text/html`, and a short list of others) —
 * the private `application/x-lexical-editor` flavor Lexical writes on copy is not one of them, so
 * the `DataTransfer` `pasteSelection` (`clipboard.utils.ts`) rebuilds from `navigator.clipboard.
 * read()` can never contain it. A real Ctrl+V — even a same-editor paste of the editor's own
 * copy — therefore always rides `text/html`/`text/plain` like any external source. A BLANKET
 * NBSP→`~` mapping would corrupt a same-editor paste of its own copy: every display-NBSP (the
 * separator after `\f`/`\fr`/`\ft`) would become a literal `~`, turning recognized markers into
 * unknown-marker soup, and a browser-hop `\nd …\nd*` paste would come back with an unmatched
 * closer. `normalizePastedNbsp` above uses a positional rule instead, so only genuine data-NBSPs
 * become `~`.
 *
 * A MULTI-LINE payload is replayed line by line with an `INSERT_PARAGRAPH_COMMAND` dispatch
 * between lines, because no USFM line can carry a newline. Going through the COMMAND (rather than
 * `selection.insertParagraph()`) is what makes a paste into a character-style stack close and
 * reopen that stack per line, the same way Enter does. This claim runs at HIGH ahead of every
 * other paste claim, so an external paste never reaches the multi-line claims that would
 * otherwise split it — the split has to happen here. A single-line payload is one `insertText`.
 *
 * Declines (returns `false`, lets Lexical's own paste handling run) when: the payload carries a
 * same-namespace Lexical flavor (the sync `ClipboardEvent` path — a null-payload dispatch or a
 * live native paste event that still has it — keeps the exact node-tree fast path); a
 * structure-protected document's selection is one `StructureKeyboardPlugin` refuses to replace
 * ({@link $shouldBlockSelectionReplacement} — a range spanning a paragraph boundary, or one
 * containing a verse marker, the mutable `VerseNode`'s own caret included); or no text can be
 * resolved.
 *
 * A payload the `\c`/`\id` strip empties ({@link stripPastedChapterAndBookId}) is CLAIMED and
 * changes nothing: there is nothing left to replace the selection with, so the selection stays, and
 * declining would hand the raw `\c` to Lexical's own paste, which the strip exists to keep it from.
 *
 * A structure-protected document is otherwise handled HERE, with the byte rules an unprotected one
 * gets plus one of its own — `structureProtectionMode: "protected"` (Platform.Bible's Simple
 * interface mode). Declining the whole paste instead handed it to
 * `StructureKeyboardPlugin`'s html sanitizer (`$sanitizeAndInsert`), which reads `text/html` and
 * nothing else, and that cost three things protection is supposed to make SAFER: a pasted `\c 7`
 * never reached {@link stripPastedChapterAndBookId}, so it created a second chapter node and poisoned
 * every subsequent save — the exact corruption that strip exists for, present only in the protected
 * mode; NBSPs never reached {@link normalizePastedNbsp}; and a Paratext 9 clipboard's `usfm:` comments
 * were never decoded, so a P9 footnote arrived as the caller glyph its `text/plain` shows. Nor did the
 * sanitizer keep structure out: its `$sanitizeNodesForProtectedStructure` only strips verse/para
 * NODES out of an html DOM import — a shape Standard view's own `text/html` no longer carries at all
 * (it is the USFM bytes now, {@link usfmToClipboardHtml}) — and pasted marker bytes re-tokenize into
 * real markers the same way typed ones do. So protection in Standard view governs three things
 * here: SELECTION REPLACEMENT (declined above, one owner), PARAGRAPH SPLITTING (a multi-line
 * payload's newlines become single spaces and the whole thing goes in as ONE `insertText` — no
 * `INSERT_PARAGRAPH_COMMAND`, no `splitExpected` arming — matching
 * `$sanitizeNodesForProtectedStructure`'s own convention for a boundary it removes), and STRUCTURE
 * MARKERS (every paragraph marker and `\v` is dropped, {@link stripPastedBlockMarkers}: the set a
 * user cannot type under protection). Character markers, notes and figures are content and stay. A
 * same-editor copy is taken here too under protection rather than left to Lexical's rich paste,
 * for the same reason (see the decline below).
 *
 * The same-namespace-flavor decline is SUSPENDED whenever the selection TOUCHES attribute-display
 * text at either end ({@link $isSelectionInAttributeContext}). Lexical's default rich-paste node
 * insertion has no notion that an attribute run's text must stay inside its one tagged TextNode,
 * and (see `attributeContextPasteFidelity.test.tsx`'s "root cause" describe) merges the run, the
 * closing glyph, and even the FOLLOWING paragraph's own sibling text into one plain node: the
 * attribute display and the closing marker both vanish, and the pasted bytes end up loose in body
 * content. The suspension covers: (1) a live native paste event that still carries a
 * same-namespace `application/x-lexical-editor` flavor, which unlike the
 * reconstructed-`DataTransfer` path can still reach a handler; (2) a
 * multi-line plain-text payload, which the ordinary external-paste pipeline below would split into
 * real paragraphs via `INSERT_PARAGRAPH_COMMAND` — inside an attribute run that is exactly as
 * destructive as the rich-paste shape; (3) a marker-bearing payload (`\c 5`) landing wholly INSIDE
 * one attribute node, where the ordinary pipeline's `stripPastedChapterAndBookId` would eat bytes
 * out of an attribute VALUE that were never a chapter token to begin with — bytes merely TOUCHING
 * a run get that strip, since they end up as re-tokenizing paragraph content
 * ({@link $insertPastedTextIntoAttributeContext}); (4) a MIXED selection (one end inside the run,
 * one end outside) combined with either (1) or (2) above — the selection touches attribute
 * context, so it must not be allowed to reach either risky branch merely because its OTHER end
 * sits outside. Attribute value bytes are never rich content — a user cannot "type formatting"
 * into one either — so this handler must always claim a paste touching one and insert it as plain
 * text ({@link $insertPastedTextIntoAttributeContext}), regardless of what other MIME flavors the
 * clipboard also carries. A protected document DOES need special handling in that branch:
 * `$insertPastedTextIntoAttributeContext` strips structure markers under protection the same way
 * the body-content path does, because a value-byte paste that re-tokenizes its `\v`/paragraph-marker
 * bytes (the paste-≡-typing carve-out above) would otherwise add the very structure protection
 * exists to keep out. One further precedence is unaffected by this suspension: the CRITICAL-priority in-note
 * multi-line `PASTE_COMMAND` claim (`MarkerEditPlugin.tsx`) still runs BEFORE this handler and
 * still wins for a multi-line payload whose selection touches EXPANDED note content — an attribute
 * run that happens to sit inside an expanded note's content is reached by this handler (and this
 * suspension) only when that in-note claim itself declines.
 *
 * Mutating: call inside `editor.update()`. It inserts text, removes the selected range, and
 * dispatches `INSERT_PARAGRAPH_COMMAND` against the editor it reads from `$getEditor()` — none of
 * which has an editor state to act on outside an update.
 */
export function $handlePasteForStandardView(
  event: ClipboardEvent | null | undefined,
  isStructureProtected = false,
  armSplitExpected: () => void = () => undefined,
  getMarker: MarkerLookup = () => undefined,
  nbspSpelling = "~",
): boolean {
  const payload = getPastePayload(event, $getEditor()._config.namespace);
  if (!payload) return false;
  return $insertTransferForStandardView(
    payload,
    () => event?.preventDefault(),
    isStructureProtected,
    armSplitExpected,
    getMarker,
    nbspSpelling,
  );
}

/**
 * Standard-view DROP: a drop's data goes in exactly as a paste of the same data does
 * ({@link $handlePasteForStandardView}), so its control characters, no-break spaces, `\c`/`\id`
 * tokens and lines get the same rules. Lexical's own insertion reads none of them: a dropped U+00A0
 * would go in as display spacing and save as a space, and a dropped U+001A as the stand-in for a
 * stored no-break space. Declines what a paste declines.
 *
 * A drop arrives as `CONTROLLED_TEXT_INSERTION_COMMAND` with the `insertFromDrop` input event.
 * Mutating: call from that command's handler, before Lexical's own insertion.
 *
 * @param dataTransfer The drop's data.
 * @param isStructureProtected Whether the document is structure-protected.
 * @param armSplitExpected Arms the engine's `splitExpected` flag for a multi-line replay.
 * @param getMarker The editor's stylesheet lookup, which says which dropped markers are structure.
 * @param nbspSpelling What a stored NBSP displays as (`getNbspSpelling`).
 * @returns Whether the drop is claimed.
 */
export function $handleDropForStandardView(
  dataTransfer: DataTransfer,
  isStructureProtected: boolean,
  armSplitExpected: () => void,
  getMarker: MarkerLookup,
  nbspSpelling: string,
): boolean {
  return $insertTransferForStandardView(
    getDataTransferPayload(dataTransfer, $getEditor()._config.namespace),
    () => undefined,
    isStructureProtected,
    armSplitExpected,
    getMarker,
    nbspSpelling,
  );
}

/**
 * Drag data for a drag out of Standard view: the same USFM text and html a copy of the selection
 * writes ({@link $getStandardViewClipboardData}), in place of the browser's own picture of the
 * display — which carries the display's characters, the internal stand-in for a stored no-break
 * space among them, to wherever the drop lands. No internal flavor: a drop is read as text
 * ({@link $handleDropForStandardView}).
 *
 * Read-only: call from a `DRAGSTART_COMMAND` handler; it never claims the drag.
 *
 * @param event The drag's `dragstart` event.
 * @param editor The editor.
 * @param nbspSpelling What a stored NBSP displays as (`getNbspSpelling`).
 */
export function $setStandardViewDragData(
  event: DragEvent,
  editor: LexicalEditor,
  nbspSpelling: string,
): void {
  const { dataTransfer } = event;
  if (!dataTransfer) return;
  const data = $getStandardViewClipboardData(editor, nbspSpelling);
  if (!data) return;
  dataTransfer.clearData();
  for (const type of ["text/plain", "text/html"] as const) {
    const value = data[type];
    if (value) dataTransfer.setData(type, value);
  }
}

function $insertTransferForStandardView(
  payload: PastePayload,
  preventDefault: () => void,
  isStructureProtected: boolean,
  armSplitExpected: () => void,
  getMarker: MarkerLookup,
  nbspSpelling: string,
): boolean {
  const selection = $getSelection();
  const inAttributeContext =
    $isRangeSelection(selection) && $isSelectionInAttributeContext(selection);
  // A same-editor copy keeps Lexical's own node-tree paste, except under structure protection:
  // there it would reach `StructureKeyboardPlugin`'s html sanitizer, which inserts the copy's USFM
  // bytes as text, and the marker engine re-tokenizes them into whatever structure they carry. Its
  // `text/plain` is those same bytes, so it takes the path below, which drops the structure.
  if (!inAttributeContext && payload.isInternal && !isStructureProtected) return false;
  // The one thing protection still declines: a selection `StructureKeyboardPlugin` refuses to
  // replace. Both plugins register `PASTE_COMMAND` at `COMMAND_PRIORITY_HIGH` and this one mounts
  // first (matching `Editor.tsx`'s order), so claiming such a paste here would starve the refusal
  // and leave the rule with two owners that could disagree.
  if (
    isStructureProtected &&
    $isRangeSelection(selection) &&
    $shouldBlockSelectionReplacement(selection)
  )
    return false;
  // `text` is the USFM decoded from a Paratext 9 clipboard's html, else `text/plain` when the
  // clipboard carries any, else the decoded `text/html` — the one preference every paste claim in
  // this editor shares, with line endings already normalized to bare `\n` ({@link getPastePayload}),
  // so no `\r` ever reaches content and a `\r\n` clipboard breaks into lines correctly.
  const { text } = payload;
  if (!text) return false;
  if (!$isRangeSelection(selection)) return false;
  preventDefault();
  if (inAttributeContext) {
    $insertPastedTextIntoAttributeContext(
      selection,
      text,
      isStructureProtected,
      getMarker,
      nbspSpelling,
    );
    return true;
  }
  $insertPastedText(
    selection,
    text,
    isStructureProtected,
    armSplitExpected,
    getMarker,
    nbspSpelling,
  );
  return true;
}

/**
 * Inserts an external paste's resolved text at `selection` the way {@link $handlePasteForStandardView}
 * does: `\c`/`\id` tokens dropped ({@link stripPastedChapterAndBookId}), NBSPs normalized
 * positionally ({@link normalizePastedNbsp}), and the lines replayed as the user would type them —
 * or, in a structure-protected document, its structure markers dropped
 * ({@link stripPastedBlockMarkers}) and its lines joined into one. Exported for the chapter-line paste
 * and drop claims (`chapterLine.utils.ts`), which must put the same bytes into the document.
 *
 * Mutating: call inside `editor.update()`.
 *
 * @param selection Where the text goes; a range is replaced.
 * @param text The resolved text ({@link getPastePayload}), line endings already normalized.
 * @param isStructureProtected Whether the document is structure-protected.
 * @param armSplitExpected Arms the engine's `splitExpected` flag for a multi-line replay.
 * @param getMarker The editor's stylesheet lookup, which says which pasted markers are structure.
 * @param nbspSpelling What a stored NBSP displays as (`getNbspSpelling`).
 */
export function $insertPastedText(
  selection: RangeSelection,
  text: string,
  isStructureProtected: boolean,
  armSplitExpected: () => void,
  getMarker: MarkerLookup,
  nbspSpelling: string,
): void {
  const withoutChapterOrBookId = stripPastedChapterAndBookId(text);
  const normalized = normalizePastedNbsp(
    isStructureProtected
      ? stripPastedBlockMarkers(withoutChapterOrBookId, getMarker)
      : withoutChapterOrBookId,
    nbspSpelling,
  );
  if (!normalized) return;
  const lines = normalized.split("\n");
  // A protected document never gains a paragraph from a paste: each newline becomes a single space
  // and the payload goes in as one insertion, so the block structure the user sees is exactly the
  // one they had. Every byte-level rule above still applied.
  if (isStructureProtected) {
    selection.insertText(lines.join(" "));
    return;
  }
  if (lines.length < 2) {
    selection.insertText(normalized);
    return;
  }
  // The engine's own INSERT_PARAGRAPH_COMMAND handler arms `splitExpected` for each dispatch
  // below, but the FIRST line is inserted before any of them run, so the flag is armed up front
  // too: every fresh prefix-less paragraph this paste creates needs its marker prefix injected
  // rather than being read as marker-deleted and merged back into the paragraph above. The
  // LOW-priority PASTE_COMMAND arm that covers the pastes reaching it never runs once this
  // HIGH-priority claim consumes the command.
  armSplitExpected();
  // Replayed as the two steps the user would have performed by hand: text, then the command.
  // The selection is removed up front rather than relying on the first `insertText` to replace
  // it, since a payload whose first line is empty (a leading newline) inserts no text at all
  // and would otherwise split a still-selected range.
  if (!selection.isCollapsed()) selection.removeText();
  const editor = $getEditor();
  lines.forEach((line, index) => {
    if (index > 0) editor.dispatchCommand(INSERT_PARAGRAPH_COMMAND, undefined);
    if (line === "") return;
    const lineSelection = $getSelection();
    if ($isRangeSelection(lineSelection)) lineSelection.insertText(line);
  });
}

/**
 * Whether `node` is a collapsed note's internal display separator: a bare single-NBSP text node
 * `createNote` (`usj-editor.adaptor.ts`) inserts purely so a caller/content children render apart
 * on screen. USFM never needs a byte to separate a closing marker from the next `\marker` token,
 * so only ONE placement of this family has a real source counterpart — the separator directly
 * after the caller, which is the mandatory space between a note's caller and its first content
 * marker (`\f + \fr …`). Every other placement (between content children, before the note's own
 * closing marker) has nothing in the source USFM to reproduce and must contribute nothing.
 */
function $isNoteInternalDisplaySeparator(node: TextNode): boolean {
  if (node.getTextContent() !== NBSP) return false;
  const parent = node.getParent();
  if (!$isNoteNode(parent)) return false;
  return !$isImmutableNoteCallerNode(node.getPreviousSibling());
}

/**
 * The `\cat …\cat*` bytes a COLLAPSED note's category needs, contributed by the one display node
 * that sits where those bytes belong: the separator directly after the caller. `""` for every
 * other node, and for a note with no category.
 *
 * A collapsed note deliberately displays no category at all — `createNote` (`usj-editor.adaptor.ts`)
 * builds the `\cat` run only for the editable EXPANDED layout, mirroring `\va`/`\vp`. That is a
 * view decision, and it is not a licence for the copy to drop the attribute: this is the same rule
 * that already recovers a collapsed note's caller from an `ImmutableNoteCallerNode` that renders as
 * an empty glyph — what you COPY is the note's bytes, not the note's pixels.
 *
 * Scoped to the collapsed layout by construction: only that layout puts an
 * `ImmutableNoteCallerNode` before this separator (the expanded one uses a plain caller TextNode
 * and carries the real `\cat` run among its children), so an expanded note can never double-emit.
 * Placed AFTER the separator's own space and with none of its own, which is where the file has the
 * span: `\f + \cat People\cat*\fr 1:1 …` — a trailing space here would re-tokenize into a stray
 * text child inside the note.
 *
 * `isLast` is what keeps it inside the selection. These bytes stand for the region AFTER the
 * separator, so a selection that STOPS there covers none of them: emitting anyway put
 * `\cat People\cat*` on the clipboard for a range the user never selected, with no `\f` opener in
 * front of the run that followed (`\f -\cat People\cat*`). The sibling caller rule
 * guards its own boundary the same way.
 *
 * The category's no-break spaces are spelled `nbspSpelling`, as the rest of the copy's display
 * text spells them, so the caller's one respelling covers these bytes too.
 */
function $collapsedNoteCategoryBytes(
  node: TextNode,
  isLast: boolean,
  nbspSpelling: string,
): string {
  if (isLast) return "";
  if (node.getTextContent() !== NBSP) return "";
  const note = node.getParent();
  if (!$isNoteNode(note)) return "";
  if (!$isImmutableNoteCallerNode(node.getPreviousSibling())) return "";
  const category = note.getCategory();
  return category ? `\\cat ${nbspValueToDisplay(category, nbspSpelling)}\\cat*` : "";
}

/** The nearest enclosing `NoteNode`'s USJ caller value, falling back to the auto-generated-caller
 * marker (`+`) when the note has none set. */
function $noteCallerText(callerNode: LexicalNode): string {
  const noteNode = callerNode.getParent();
  const caller = $isNoteNode(noteNode) ? noteNode.getCaller() : undefined;
  return caller || GENERATOR_NOTE_CALLER;
}

/**
 * Whether this block-level element opens a new LINE of copied USFM, or is engine-internal to an
 * opaque construct and must stay on the construct's own line.
 *
 * A sidebar's nested `\p` and a table's rows and cells are real block-level nodes, so the walk's
 * "one `\n` per non-inline boundary" rule would spread ONE construct over several lines. A paste of
 * that text replays every `\n` as a paragraph split, and Tier 2 re-tokenizes strictly one paragraph
 * at a time (`$requestTier2ForNode` always rebuilds a single-element array), so the `\esb`/`\esbe`
 * and `\tr`/`\th`/`\tc` assembly `usfmFragmentToUsj.ts` already implements never sees the whole
 * construct in one pass: the sidebar comes back unclosed with its paragraph hoisted out, and the
 * table comes back as empty row wrappers with the cells stranded as sibling paragraphs.
 *
 * Keeping the construct byte-contiguous is what lets a single-paragraph rebuild reassemble it. USFM
 * markers self-delimit, so the one-line form is valid USFM of the same document — just not the
 * line-per-marker layout a USFM writer would emit, which is a deliberate trade for a paste that
 * survives.
 *
 * The construct's own outermost node still starts its own line: only a block boundary with an
 * opaque ancestor ABOVE it is suppressed, so a table stays separated from the prose around it.
 */
function $startsBlockLine(node: LexicalNode): boolean {
  const parent = node.getParent();
  return !parent || $opaqueBlockAncestor(parent) === undefined;
}

/**
 * Source-faithful USFM text of `selection` — the `text/plain` leg of Standard-view copy/cut. Walks
 * `selection.getNodes()` the same way `RangeSelection.getTextContent()` does — mirrored from
 * lexical 0.43.0, so a Lexical upgrade should re-read that walk and confirm it still matches
 * before trusting this one — (single `\n` between
 * non-inline block boundaries, anchor/focus offsets respected on the boundary text nodes,
 * `DecoratorNode`s contributing their own text; an inline element like `AttributeRunNode` or
 * `NoteNode` contributes nothing itself, its children being walked as their own list entries), with
 * two USFM-specific corrections:
 *
 * 1. An `ImmutableNoteCallerNode` — which renders as `""` on screen for a collapsed note with an
 *    auto-generated caller — contributes the enclosing note's real USJ caller (`+`, `-`, or a
 *    literal), preceded by the separating space it stands after (the mandatory space after
 *    `\f`/`\x`) unless the selection STARTS at the caller, leaving that opener out. The node
 *    itself is left untouched (`getTextContent()` still returns `""`): it serves every view mode,
 *    and formatted-view prose copy depends on staying caller-free.
 * 2. NBSP inverts to a plain space per node instead of via a blanket `replaceAll` — a note's
 *    internal display-only separators (`$isNoteInternalDisplaySeparator`) contribute nothing
 *    instead of becoming phantom spaces; every other NBSP (marker-trailing spaces, a char span's
 *    structural leading separator, a verse's own marker-to-number gap, the `\id` line's
 *    book-code separator a decorator carries) represents a real source space and still maps to
 *    one. A data NBSP is displayed as `nbspSpelling`: `~` is already its USFM spelling and is left
 *    alone, and any other spelling (`NBSP_STAND_IN`, where `~` is an ordinary character and the
 *    project stores U+00A0 itself) is written as U+00A0.
 * 3. A block boundary INSIDE an opaque construct contributes no line break, so the construct
 *    copies out on ONE line (see {@link $startsBlockLine}).
 *
 * Read-only: safe inside `editor.getEditorState().read(...)`, an `editor.update(...)`, or a command
 * handler.
 */
export function $selectionToUsfmText(selection: RangeSelection, nbspSpelling = "~"): string {
  const nodes = selection.getNodes();
  if (nodes.length === 0) return "";
  const firstNode = nodes[0];
  const lastNode = nodes[nodes.length - 1];
  const { anchor, focus } = selection;
  const isBefore = anchor.isBefore(focus);
  const [anchorOffset, focusOffset] = $getCharacterOffsets(selection);
  let text = "";
  let prevWasElement = true;
  for (const node of nodes) {
    if ($isElementNode(node) && !node.isInline()) {
      if (!prevWasElement && $startsBlockLine(node)) text += "\n";
      prevWasElement = !node.isEmpty();
      continue;
    }
    prevWasElement = false;
    if ($isImmutableNoteCallerNode(node)) {
      if (node !== lastNode || !selection.isCollapsed())
        text += (node === firstNode ? "" : " ") + $noteCallerText(node);
    } else if ($isTextNode(node)) {
      let nodeText = node.getTextContent();
      if (node === firstNode) {
        if (node === lastNode) {
          if (
            anchor.type !== "element" ||
            focus.type !== "element" ||
            focus.offset === anchor.offset
          )
            nodeText =
              anchorOffset < focusOffset
                ? nodeText.slice(anchorOffset, focusOffset)
                : nodeText.slice(focusOffset, anchorOffset);
        } else nodeText = isBefore ? nodeText.slice(anchorOffset) : nodeText.slice(focusOffset);
      } else if (node === lastNode) {
        nodeText = isBefore ? nodeText.slice(0, focusOffset) : nodeText.slice(0, anchorOffset);
      }
      text += $isNoteInternalDisplaySeparator(node)
        ? ""
        : nodeText.replaceAll(NBSP, " ") +
          $collapsedNoteCategoryBytes(node, node === lastNode, nbspSpelling);
    } else if (
      ($isDecoratorNode(node) || $isLineBreakNode(node)) &&
      (node !== lastNode || !selection.isCollapsed())
    ) {
      text += node.getTextContent().replaceAll(NBSP, " ");
    }
  }
  return nbspSpelling === "~" ? text : text.replaceAll(nbspSpelling, NBSP);
}

/**
 * The `text/html` clipboard flavor for `usfm` — the SAME bytes as `text/plain`, HTML-escaped and
 * laid out one block per line.
 *
 * Standard view's fidelity carrier is USFM text (`docs/clipboard-semantics.md`), and the two
 * flavors a clipboard consumer can actually read must therefore decode to the same document.
 * Lexical's own DOM export cannot provide that, in two independent ways:
 * `ImmutableNoteCallerNode.exportDOM` carries a collapsed note's caller as a `data-caller`
 * ATTRIBUTE with no text at all, so the note's html reads back as `\f \fr …\f*` with the caller
 * missing — and Paratext 9 reads an incoming fragment's TEXT as USFM, so a P10→P9 note paste
 * arrived with an empty caller; and `UnknownNode.exportDOM` returns `{element: null}` for every
 * kind, which stops `@lexical/html`'s walk before it reaches the node's display children, so
 * figures, sidebars, peripherals, refs and optbreaks are absent from the html altogether. Rendering
 * the copy walker's own USFM makes both losses structurally impossible rather than patched.
 *
 * Each `\n`-separated line becomes `<p><span style="white-space: pre-wrap;">…</span></p>` — the
 * shape Lexical's own `TextNode.exportDOM` produces for a paragraph of text, so an html consumer
 * that re-imports through `$generateNodesFromDOM` (shared-react's `StructureKeyboardPlugin` still
 * sanitizes a protected DROP that way, and a foreign consumer may rebuild nodes from html at all)
 * still sees one block per line.
 * `white-space: pre-wrap` is what keeps an edge space and a run of spaces alive through such a
 * re-import; P9 ignores the style and reads the text. An empty line becomes a bare `<p></p>`. The
 * copy walker produces one only for an empty top-level block inside the selection, and that is the
 * one place the two flavors part: {@link htmlPasteText} collapses newline runs and trims the outer
 * ones for every html source it reads, so a blank line survives in `text/plain` alone.
 *
 * `&`, `<` and `>` are escaped, `&` first so an escape's own ampersand is not escaped twice. USFM
 * needs nothing else escaped here: the bytes live in a text node, where quotes and backslashes are
 * literal.
 */
export function usfmToClipboardHtml(usfm: string): string {
  return usfm
    .split("\n")
    .map((line) => line.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;"))
    .map((line) =>
      line ? `<p><span style="white-space: pre-wrap;">${line}</span></p>` : "<p></p>",
    )
    .join("");
}

/**
 * Whether any node of `selection` is, or sits inside, a `BookNode` or `ChapterNode` — a structure
 * USFM allows once per book, which a paste must never duplicate.
 */
function $selectionTouchesBookOrChapter(selection: RangeSelection): boolean {
  return selection
    .getNodes()
    .some((node) =>
      [node, ...node.getParents()].some(
        (ancestor) => $isBookNode(ancestor) || $isChapterNode(ancestor),
      ),
    );
}

/**
 * Payload builder: the currently-selected content, normalized per flavor. `text/plain` is the
 * source-faithful USFM of the selection ({@link $selectionToUsfmText}), which carries plain spaces
 * where the display shows NBSP. `text/html` is those SAME bytes as escaped html
 * ({@link usfmToClipboardHtml}), so a consumer's flavor choice can never change the content it
 * receives. The internal `application/x-lexical-editor` flavor keeps the display form untouched so a
 * paste back into a Standard-view editor round-trips exactly. Shared by both the real-event and
 * null-event branches of `$handleCopyForStandardView` below so they stay byte-for-byte consistent.
 *
 * The internal flavor is OMITTED whenever an END of the selection lies inside an opaque construct
 * (`$selectionReachesIntoOpaqueBlock`, shared-react). That flavor exists to carry a construct WHOLE,
 * and a selection cutting through one cannot be carried whole: `createUnknown`
 * (`usj-editor.adaptor.ts`) builds a construct's text children in token mode, and
 * `$sliceSelectedTextNodeContent` (`@lexical/selection`) refuses to slice a token-mode TextNode, so
 * a caption selected from its third character to its seventh serializes as the COMPLETE construct —
 * wrapper, every attribute on it, and the caption's full text. Pasting that reproduces a whole
 * second figure where the user asked for four letters, and a save persists the invented bytes with
 * no error. The two text flavors have no such floor: they are exactly the selected bytes, and
 * Tier 2 re-tokenizes them back into whatever construct those bytes actually spell (an unclosed
 * `\fig` becomes a char span, not a figure — which is what a cut-through selection means).
 *
 * A selection whose ends are both OUTSIDE still ships the flavor: the construct is covered whole
 * there, and the fast path rebuilds it with a fidelity re-tokenization cannot match for the kinds
 * USFM has no bytes for (`ref`).
 *
 * The internal flavor is omitted, too, for a selection touching a book or chapter line
 * ({@link $selectionTouchesBookOrChapter}). The fast path would rebuild the copied `BookNode`/
 * `ChapterNode` verbatim — or, for a selection starting inside the line, its glyph text, which
 * re-tokenizes into one — past the `\c`/`\id` strip every text paste gets
 * ({@link stripPastedChapterAndBookId}), and a second chapter node makes every later save of the
 * chapter fail. Only a paste that arrives as a real `ClipboardEvent` (Shift+Insert, the browser's
 * own context-menu Paste) can read the flavor at all, so the text flavors are what Ctrl+V gets in
 * any case.
 */
export function $getStandardViewClipboardData(
  editor: LexicalEditor,
  nbspSpelling = "~",
): LexicalClipboardData | undefined {
  const selection = $getSelection();
  if (!$isRangeSelection(selection) || selection.isCollapsed()) return undefined;
  const usfm = $selectionToUsfmText(selection, nbspSpelling);
  const data: LexicalClipboardData = {
    "text/plain": usfm,
    "text/html": usfmToClipboardHtml(usfm),
  };
  if ($selectionReachesIntoOpaqueBlock() || $selectionTouchesBookOrChapter(selection)) return data;
  const lexical = $getLexicalContent(editor);
  // The internal flavor is the editor's own nodes, so it holds the stand-in for a stored no-break
  // space (`NBSP_STAND_IN`) as it is, and the stand-in must not leave the editor. Without the
  // flavor the paste takes the text, which spells the no-break space as U+00A0.
  if (lexical && !holdsNbspStandIn(lexical)) data["application/x-lexical-editor"] = lexical;
  return data;
}

/** Whether serialized editor JSON holds the stand-in, either as itself or escaped (`\u001a`). */
function holdsNbspStandIn(json: string): boolean {
  return json.includes(NBSP_STAND_IN) || /\\u001a/i.test(json);
}

/**
 * Clipboard text carries plain spaces where the display shows NBSP.
 *
 * Also the last line of defense for an EMPTY copy. A dispatch with no clipboard event of its own
 * cannot simply be declined: `@lexical/rich-text` picks it up and has `@lexical/clipboard`
 * synthesize an event — a hidden placeholder element is appended to the editor, the DOM selection
 * pointed at it, and `document.execCommand("copy")` run to provoke a real clipboard event to fill
 * in. With nothing selected, the filling step bails BEFORE it suppresses the browser's own copy,
 * and the browser copies the placeholder, replacing the clipboard's real contents with a character
 * that was never in the document. Standard view is where a caret most often has nothing copyable
 * around it — a click on a read-only construct (a figure, a table) leaves the caret beside it
 * rather than inside — so a null-payload dispatch with no content behind it is CLAIMED here and
 * does nothing, which is what copying an empty selection means. shared-react's
 * `registerEmptyCopyGuard` states the same rule for every view, one priority lower; claiming here
 * too keeps the rule from depending on which plugins a host happens to mount.
 *
 * A selection that is merely not a RANGE (a node selection) is still declined: it has real content,
 * and the synthesized-event path copies it correctly.
 *
 * `copyLimit` is `EditorOptions.copyLimit`; see {@link $writeCopyPayload}. While it is set, no
 * `application/x-lexical-editor` flavor is written: it carries each note caller's preview text,
 * which is the note's whole text, and so can hold more than the USFM the limit is measured on.
 *
 * Mutating when `isCut`: call inside `editor.update()` — in practice, from a `COPY_COMMAND` or
 * `CUT_COMMAND` handler.
 */
export function $handleCopyForStandardView(
  event: ClipboardEvent | null | undefined,
  editor: LexicalEditor,
  isCut: boolean,
  copyLimit?: number,
  nbspSpelling = "~",
): boolean {
  const selection = $getSelection();
  if (!$isRangeSelection(selection) || selection.isCollapsed()) {
    const isNullPayloadDispatch = !event || !("clipboardData" in event);
    // The same predicate shared-react's guard uses, not a second spelling of it: the two layers
    // have to agree on what "nothing to copy" means — including that a node selection has real
    // content and is therefore declined here — and one shared function is what keeps them agreeing.
    return isNullPayloadDispatch && !$hasCopyableSelection();
  }
  const data = $getStandardViewClipboardData(editor, nbspSpelling);
  if (!data) return false;
  if (copyLimit !== undefined) delete data["application/x-lexical-editor"];
  return $writeCopyPayload(event, editor, selection, data, isCut, copyLimit);
}

/**
 * Writes a copy or cut's `data` to the clipboard through whichever leg delivered the command, and
 * claims it — shared by Standard view's handler above and the Markers view's
 * (`MarkersViewCopyPlugin.tsx`), so both write their payloads the same way.
 *
 * A cut removes the range only when the editor is editable: `ClipboardPlugin`'s Ctrl+X listener
 * (and `ContextMenuPlugin`/`EditorRef`) dispatches `CUT_COMMAND` with no editability check of its
 * own, so a read-only surface reaching this function must still copy and remove nothing. The rule
 * lives here rather than at each call site so every caller gets it.
 *
 * `copyLimit` is `EditorOptions.copyLimit`. `CopyLimitPlugin` fits the selection to it before this
 * runs, so `data` already fits. If it does not, a development build warns, and only the first
 * `copyLimit` code units of the plain text are written, with nothing removed. While it is set, a
 * browser copy whose page selection runs outside the editor is declined, for the page guard.
 *
 * Mutating when `isCut`: call inside `editor.update()` — in practice, from a `COPY_COMMAND` or
 * `CUT_COMMAND` handler.
 */
export function $writeCopyPayload(
  event: ClipboardEvent | null | undefined,
  editor: LexicalEditor,
  selection: RangeSelection,
  data: LexicalClipboardData,
  isCut: boolean,
  copyLimit?: number,
): boolean {
  const limit = normalizeCopyLimit(copyLimit);
  if (limit !== undefined && isCopyFromOutsideEditor(editor, event)) return false;
  const plain = data["text/plain"] ?? "";
  if (limit !== undefined && plain.length > limit) {
    if (process.env.NODE_ENV !== "production") {
      // eslint-disable-next-line no-console -- Intentional developer warning: a caller skipped the fit.
      console.warn(
        "@eten-tech-foundation/platform-editor: a copy reached the clipboard over its copy limit; " +
          "writing shortened plain text only.",
      );
    }
    return $writeClipboardData(event, editor, { "text/plain": sliceToCopyLimit(plain, limit) });
  }
  // A RANGE can cover nodes that contribute no bytes at all (a construct with no children left,
  // selected by the two element points either side of it). `$writeClipboardData` then writes
  // nothing but still claims the command, and a cut still removes the range: the bytes it would
  // have carried are the ones that do not exist, not the nodes.
  return $writeClipboardData(
    event,
    editor,
    data,
    isCut && editor.isEditable() ? () => selection.removeText() : undefined,
  );
}

/**
 * Writes `data` to the clipboard through whichever leg delivered a copy or cut command, claims the
 * command, then runs `$remove` if one is given (a cut's removal). A payload with no plain text
 * writes nothing, leaving the clipboard's contents as they were, but the command is still claimed.
 * Declines (returns `false`) only for a native clipboard event whose data store is unavailable.
 *
 * Mutating when `$remove` is given: call inside `editor.update()` — in practice, from a
 * `COPY_COMMAND` or `CUT_COMMAND` handler.
 */
export function $writeClipboardData(
  event: ClipboardEvent | null | undefined,
  editor: LexicalEditor,
  data: LexicalClipboardData,
  $remove?: () => void,
): boolean {
  // Keyed on the readable bytes alone: the internal flavor serializes an empty range as an empty
  // `nodes` array, which is still a non-empty string. Writing an empty payload would replace the
  // clipboard's real contents with an empty string and an empty `<p>`.
  const isEmptyPayload = !data["text/plain"];
  if (!event || !("clipboardData" in event)) {
    // Null-payload dispatch (ClipboardPlugin / ContextMenuPlugin / EditorRef): write via
    // Lexical's execCommand mechanism with OUR pre-normalized payload. copyToClipboard(null)
    // without `data` would intercept its own synthesized event at COMMAND_PRIORITY_CRITICAL
    // and write the stock payload — which is why this branch must pass `data`.
    if (!isEmptyPayload) void copyToClipboard(editor, null, data);
    $remove?.();
    return true;
  }
  // Event-shaped payload whose clipboardData is null/absent: decline outright. This is an
  // in-flight native clipboard event whose data store isn't accessible — routing it into the
  // null-dispatch leg above would re-enter document.execCommand from inside that dispatch and
  // never preventDefault the original event.
  if (event.clipboardData == null) return false;
  event.preventDefault();
  if (!isEmptyPayload)
    for (const [mime, value] of Object.entries(data)) event.clipboardData.setData(mime, value);
  $remove?.();
  return true;
}
